// Single place for the two secrets. Code-node pass-through is reliable in
// n8n 2.x (unlike Set nodes, which dropped the payload in this setup).
const inp = $json || {};
return [{ json: { ...inp, N8N_WEBHOOK_SECRET: 'PASTE_N8N_WEBHOOK_SECRET_HERE', GROQ_API_KEY: 'PASTE_GROQ_API_KEY_HERE' } }];

const crypto = require('crypto');
// HMAC-SHA256 verification. The secret arrives from the "Config" node chained
// upstream. JSON.stringify preserves the key order of the received body, so it
// reproduces the exact string Next.js signed in lib/n8n.ts.
const inp = $input.first().json || {};
const secret = String(inp.N8N_WEBHOOK_SECRET || inp.webhookSecret || '');
const headers = inp.headers || {};
const sig = String(headers['x-signature'] || headers['X-Signature'] || '');
const body = inp.body;
// n8n 2.x may deliver the body already parsed (object) or as the raw string.
const bodyStr = typeof body === 'string' ? body : JSON.stringify(body || {});
const computed = crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');
const valid = sig.length > 0 && secret.length > 0 && sig === computed;
return [{ json: { ...inp, valid: valid } }];

const inp = $input.first().json || {};
const apiKey = String(inp.GROQ_API_KEY || inp.apiKey || '');
// The signed payload is nested under .body on the webhook item — reading it off
// the root was why callbackUrl used to come out empty. Mirror the string/object
// tolerance of the Verify Signature node.
const rawBody = inp.body;
let payload = {};
try {
  payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : (rawBody || {});
} catch (e) {
  payload = {};
}
const transcript = Array.isArray(payload.transcript) ? payload.transcript : [];
let lines = transcript.map(function (t) { return t.speaker + ': ' + t.text; }).join('\n');

// Rules text + the literal JSON schema, baked at build time from
// lib/analysis-contract.json. Must stay byte-identical to buildSystemPrompt()
// in lib/groq.ts. Groq's json_object mode enforces no shape, so omitting the
// schema here makes the model invent its own keys — an earlier build did
// exactly that and silently dropped resolution/risk/customer.
const systemPrompt = "You are CallLens, a precise conversation-intelligence engine. You analyze call-centre transcripts and return ONLY strict JSON matching the schema below. No prose, no markdown fences.\n\nHARD RULES — these determine your quality score, never violate them:\n1. Classify sentiment from MEANING and CONTEXT, not keyword matching. \"I am not unhappy\" is NOT negative. Read the conversation, not the dictionary.\n2. Prefer an evidence-based ESTIMATE over a null. Use null (or \"unknown\") ONLY when the transcript genuinely carries no signal for that field. A billing complaint that ends with the agent issuing a refund IS resolved — say so.\n3. agent.* fields are null only if NO speaker can be identified as the agent/rep/support/advisor.\n4. customer.* fields are null only if NO speaker can be identified as the customer/caller. For fully unlabeled transcripts, infer roles from behaviour (who reports a problem vs who offers a fix) rather than refusing.\n5. Never expose chain-of-thought. Every explanation must be a short, evidence-backed sentence grounded in the transcript.\n6. Enums: use ONLY the allowed values. Every sentence gets positive|neutral|negative.\n7. sentences[]: emit EXACTLY ONE object per input turn, and `seq` MUST match that turn's seq exactly. Never merge turns, never skip one, never invent one.\n8. Every sentence object MUST include `evidence`: a verbatim fragment of at most 15 words, copied from that turn, that justifies the label.\n9. Sentiment `score` is 0-100 (50 = neutral). `confidence` is 0-1.\n10. important_moments: up to 6 moments that changed the conversation's direction. Never cite a seq that does not exist.\n11. emotions: up to 5 aggregate emotion labels with 0-100 intensity.\n12. reasoning.drivers: 2-5 factors that most determined the overall sentiment, each with a direction, a 0-100 weight, and a verbatim quote. reasoning.counter_signals: evidence that pointed the OTHER way and that you weighed but did not follow. This is how you show your work — it is graded.\n\nReturn the JSON object ONLY.\n\nSCHEMA — your reply must be a single JSON object with EXACTLY these keys and types:\n{\"type\":\"object\",\"required\":[\"overall_sentiment\",\"summary\",\"intent\",\"resolution\",\"risk\",\"customer\",\"agent\",\"emotions\",\"important_moments\",\"reasoning\",\"sentences\"],\"properties\":{\"overall_sentiment\":{\"type\":\"object\",\"required\":[\"label\",\"score\",\"confidence\"],\"properties\":{\"label\":{\"type\":\"string\",\"enum\":[\"positive\",\"neutral\",\"negative\"]},\"score\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":100},\"confidence\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1}}},\"summary\":{\"type\":\"string\",\"maxLength\":500},\"intent\":{\"type\":\"object\",\"required\":[\"category\",\"description\"],\"properties\":{\"category\":{\"type\":\"string\",\"maxLength\":40},\"description\":{\"type\":\"string\",\"maxLength\":200}}},\"resolution\":{\"type\":\"object\",\"required\":[\"status\",\"likelihood\"],\"properties\":{\"status\":{\"type\":\"string\",\"enum\":[\"resolved\",\"unresolved\",\"partial\",\"unknown\"]},\"likelihood\":{\"type\":[\"integer\",\"null\"],\"minimum\":0,\"maximum\":100}}},\"risk\":{\"type\":\"object\",\"required\":[\"escalation\"],\"properties\":{\"escalation\":{\"type\":[\"integer\",\"null\"],\"minimum\":0,\"maximum\":100}}},\"customer\":{\"type\":\"object\",\"required\":[\"frustration\",\"satisfaction\",\"effort\"],\"properties\":{\"frustration\":{\"type\":[\"string\",\"null\"],\"enum\":[\"low\",\"medium\",\"high\",null]},\"satisfaction\":{\"type\":[\"integer\",\"null\"],\"minimum\":0,\"maximum\":100},\"effort\":{\"type\":[\"string\",\"null\"],\"enum\":[\"low\",\"medium\",\"high\",null]}}},\"agent\":{\"type\":\"object\",\"required\":[\"empathy\",\"clarity\",\"professionalism\"],\"properties\":{\"empathy\":{\"type\":[\"integer\",\"null\"],\"minimum\":0,\"maximum\":100},\"clarity\":{\"type\":[\"integer\",\"null\"],\"minimum\":0,\"maximum\":100},\"professionalism\":{\"type\":[\"integer\",\"null\"],\"minimum\":0,\"maximum\":100}}},\"emotions\":{\"type\":\"array\",\"maxItems\":5,\"items\":{\"type\":\"object\",\"required\":[\"label\",\"intensity\"],\"properties\":{\"label\":{\"type\":\"string\",\"maxLength\":40},\"intensity\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":100}}}},\"important_moments\":{\"type\":\"array\",\"maxItems\":6,\"items\":{\"type\":\"object\",\"required\":[\"seq\",\"speaker\",\"event\"],\"properties\":{\"seq\":{\"type\":\"integer\",\"minimum\":1},\"speaker\":{\"type\":\"string\",\"maxLength\":40},\"event\":{\"type\":\"string\",\"maxLength\":200}}}},\"reasoning\":{\"type\":\"object\",\"required\":[\"drivers\",\"counter_signals\"],\"properties\":{\"drivers\":{\"type\":\"array\",\"minItems\":2,\"maxItems\":5,\"items\":{\"type\":\"object\",\"required\":[\"factor\",\"direction\",\"weight\",\"evidence\"],\"properties\":{\"factor\":{\"type\":\"string\",\"maxLength\":80},\"direction\":{\"type\":\"string\",\"enum\":[\"positive\",\"negative\"]},\"weight\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":100},\"evidence\":{\"type\":\"string\",\"maxLength\":200}}}},\"counter_signals\":{\"type\":\"array\",\"maxItems\":4,\"items\":{\"type\":\"object\",\"required\":[\"observation\",\"evidence\"],\"properties\":{\"observation\":{\"type\":\"string\",\"maxLength\":160},\"evidence\":{\"type\":\"string\",\"maxLength\":200}}}}}},\"sentences\":{\"type\":\"array\",\"minItems\":1,\"items\":{\"type\":\"object\",\"required\":[\"seq\",\"speaker\",\"text\",\"sentiment\",\"score\",\"confidence\",\"emotion\",\"evidence\"],\"properties\":{\"seq\":{\"type\":\"integer\",\"minimum\":1},\"speaker\":{\"type\":\"string\",\"maxLength\":40},\"text\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2000},\"sentiment\":{\"type\":\"string\",\"enum\":[\"positive\",\"neutral\",\"negative\"]},\"score\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":100},\"confidence\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"emotion\":{\"type\":\"string\",\"maxLength\":40},\"evidence\":{\"type\":\"string\",\"maxLength\":200}}}}}}";

// ── Token budget (mirrors planRequest() in lib/groq.ts) ──
// Groq admits a request only if prompt_tokens + max_completion_tokens is within
// the tier's TPM limit — the REQUESTED total, not actual usage. A fixed 8192
// returned HTTP 413 "Request too large" on an 11-turn transcript.
const TPM_LIMIT = 8000;
const TPM_MARGIN = 500;
const SYS_TOKENS = 1600;
const CHARS_PER_TOKEN = 3.6;
const MIN_COMPLETION = 1200;
const MAX_COMPLETION = 4096;
const MAX_USER_CHARS = 16000;

let truncatedChars = 0;
if (lines.length > MAX_USER_CHARS) {
  truncatedChars = lines.length - MAX_USER_CHARS;
  const cut = lines.slice(0, MAX_USER_CHARS);
  const lastNewline = cut.lastIndexOf('\n');
  lines = lastNewline > 0 ? cut.slice(0, lastNewline) : cut;
}
const promptTokens = SYS_TOKENS + Math.ceil(lines.length / CHARS_PER_TOKEN);
const available = TPM_LIMIT - TPM_MARGIN - promptTokens;
const maxCompletion = Math.max(MIN_COMPLETION, Math.min(MAX_COMPLETION, available));

const requestBody = {
  model: "openai/gpt-oss-120b",
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: lines }
  ],
  temperature: 0.1,
  reasoning_effort: "medium",
  max_completion_tokens: maxCompletion,
  response_format: { type: 'json_object' }
};

return [{ json: {
  ...inp,
  requestBody: requestBody,
  conversation_id: payload.conversation_id,
  file_name: payload.file_name || '',
  turnCount: transcript.length,
  truncatedChars: truncatedChars,
  GROQ_API_KEY: apiKey
} }];

// require('https') — the n8n 2.x httpRequest node mangled JSON bodies here,
// and Code nodes have neither global fetch nor $helpers. This sends the exact
// bytes we built (needs NODE_FUNCTION_ALLOW_BUILTIN=crypto,https on a
// self-hosted container — n8n Cloud allows all builtins by default).
const https = require('https');
const inp = $input.first().json || {};
const payload = JSON.stringify(inp.requestBody || {});
let status = 0;
let text = '';
let parsed = null;
await new Promise(function (resolve) {
  const req = https.request("https://api.groq.com/openai/v1/chat/completions", {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
      'Authorization': 'Bearer ' + String(inp.GROQ_API_KEY || '')
    }
  }, function (res) {
    status = res.statusCode || 0;
    res.setEncoding('utf8');
    res.on('data', function (c) { text += c; });
    res.on('end', function () {
      try { parsed = JSON.parse(text); } catch (e) { parsed = null; }
      resolve();
    });
  });
  // Never outlive the app's own budget — a hung socket here would hold the
  // caller's connection open until it timed out on its side.
  req.setTimeout(25000, function () { req.destroy(new Error('groq socket timeout')); });
  req.on('error', function (e) { text = String(e && e.message ? e.message : e); resolve(); });
  req.write(payload);
  req.end();
});
return [{ json: { ...inp, httpStatus: status, groqResponse: parsed, groqRaw: text.slice(0, 2000) } }];

// Extract the JSON text from the Groq chat-completion response and parse it.
// Routing to the 200 vs 502 Respond node happens in "Output Valid?".
// NOTE: this variable MUST be named 'inp' — the return spreads {...inp} to carry
// the whole chain forward. It was previously declared as 'item', which threw
// ReferenceError and killed every execution before it could respond.
const inp = $input.first().json || {};
const data = inp.groqResponse || {};
const choices = data.choices || [];
const msg = (choices[0] && choices[0].message) || {};
let text = typeof msg.content === 'string' ? msg.content : '';

let cleaned = text.trim();
// Groq may (rarely) wrap JSON in markdown fences — strip them before parsing.
if (cleaned.indexOf('\u0060\u0060\u0060') === 0) {
  cleaned = cleaned.replace(/^\u0060\u0060\u0060(?:json)?\s*/i, '').replace(/\s*\u0060\u0060\u0060$/, '');
}

let result = null;
let ok = false;
try {
  result = JSON.parse(cleaned);
  ok = true;
} catch (e) {
  // gpt-oss spends part of max_completion_tokens on reasoning, so a long
  // transcript can truncate the JSON. Salvage up to the last closing brace
  // rather than discarding the whole analysis.
  const lastBrace = cleaned.lastIndexOf('}');
  if (lastBrace > 0) {
    try { result = JSON.parse(cleaned.slice(0, lastBrace + 1)); ok = true; } catch (e2) { ok = false; }
  }
}
if (ok && (!result || typeof result !== 'object')) ok = false;

return [{ json: {
  ...inp,
  ok: ok,
  result: result,
  failureReason: ok ? '' : ('groq status ' + String(inp.httpStatus) + ': ' + String(inp.groqRaw || '').slice(0, 400))
} }];
